if (issuer == "lti")
{
    ValidateLti(token);
}
else if (issuer == "local")
{
    ValidateLocal(token);
}
else
{
    throw new InvalidOperationException("unknown issuer");
}

switch (issuer)
{
    case "lti":
        ValidateLti(token);
        break;
    case "local":
        ValidateLocal(token);
        break;
    default:
        throw new InvalidOperationException("unknown issuer");
}

int total = 0;
if (hasDiscount)
{
    int discount = 10;  // only visible inside this block
    total -= discount;
}
// discount is not accessible here

bool isValid;
if (token != null)
{
    isValid = Validate(token);
}
else
{
    isValid = false;
}
// compiler knows isValid is assigned on every path

switch (statusCode)
{
    case 200:
    case 201:
        LogSuccess();
        break;          // both 200 and 201 share this code
    case 404:
        LogNotFound();
        break;
    case 500:
        LogError();
        goto case 404;  // explicit fall-through to 404 handler
    default:
        LogUnknown();
        break;
}
